using DriveOS.Application.Abstractions.Messaging;using DriveOS.Application.Abstractions.Time;using DriveOS.Modules.CurriculumPedagogy.Application.Persistence;using DriveOS.Modules.CurriculumPedagogy.Domain.Readiness;using DriveOS.Modules.CurriculumPedagogy.Domain.TrainingPaths;using DriveOS.SharedKernel.Identifiers;using DriveOS.SharedKernel.Results;
namespace DriveOS.Modules.CurriculumPedagogy.Application.Readiness;
public sealed class RecordPedagogicalReadinessDecisionCommandHandler(ITrainingPathRepository paths,IPedagogicalReadinessDecisionRepository decisions,ICurriculumPedagogyUnitOfWork uow,IClock clock):ICommandHandler<RecordPedagogicalReadinessDecisionCommand,PedagogicalReadinessDecisionId>{public async Task<Result<PedagogicalReadinessDecisionId>> Handle(RecordPedagogicalReadinessDecisionCommand c,CancellationToken ct){var path=await paths.GetByIdAsync(c.TrainingPathId,c.OrganizationId,ct);if(path is null)return Result.Failure<PedagogicalReadinessDecisionId>(PedagogicalReadinessApplicationErrors.TrainingPathNotFound);if(path.Status is not TrainingPathStatus.Active and not TrainingPathStatus.Suspended)return Result.Failure<PedagogicalReadinessDecisionId>(PedagogicalReadinessApplicationErrors.TrainingPathNotEligible);var r=PedagogicalReadinessDecision.Record(PedagogicalReadinessDecisionId.New(),c.OrganizationId,path.StudentId,path.Id,c.Decision,c.Rationale,c.Conditions,c.ReviewerId,clock.UtcNow);if(r.IsFailure)return Result.Failure<PedagogicalReadinessDecisionId>(r.Error);await decisions.AddAsync(r.Value,ct);await uow.CommitAsync(ct);return Result.Success(r.Value.Id);}}
